package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.holiday.HolidayRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from";

    private final JdbcTemplate jdbc;

    private final HolidayRepository holidays;

    public ClaimRepository(JdbcTemplate jdbc, HolidayRepository holidays) {
        this.jdbc = jdbc;
        this.holidays = holidays;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC, id DESC",
                ClaimRepository::map, sheetId);
    }

    /** The claim with this id on this sheet, or null. */
    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ClaimRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Insert a new claim (null id) or update an existing one; the claim as stored. */
    public Claim save(Claim claim) {
        if (claim.id() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, due = ?, opened_by = ?, corrects = ? WHERE id = ? AND sheet_id = ?",
                    claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.status().name(), claim.number(),
                    claim.due(), claim.openedBy(), claim.corrects(), claim.id(), claim.sheetId());
            return claim;
        }
        // The terms its due-by is fixed with: the business days to it over the sheet's holidays as they stand now.
        int fixedTerms = HolidayRepository.businessDaysBetween(holidays.dates(claim.sheetId()), claim.date(),
                claim.dueBy());
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, claim_number, opened_by, split_from, fixed_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.sheetId());
            ps.setLong(2, claim.personId());
            ps.setBigDecimal(3, claim.amount());
            ps.setDate(4, Date.valueOf(claim.date()));
            ps.setString(5, claim.note());
            ps.setString(6, claim.status().name());
            ps.setString(7, claim.corrects());
            ps.setDate(8, Date.valueOf(claim.dueBy()));
            ps.setString(9, claim.number());
            ps.setString(10, claim.openedBy());
            ps.setString(11, claim.splitFrom());
            ps.setInt(12, fixedTerms);
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), false, null,
                claim.corrects(), claim.dueBy(), null, 0, claim.splitFrom());
    }

    /**
     * Works out again, from its date and the terms it was fixed with over the sheet's holidays as they stand now, the
     * due-by of every claim on the sheet that is not SETTLED or VOID and is due by on or after {@code from}.
     */
    public void refixDueBys(String sheetId, LocalDate from) {
        Set<LocalDate> sheetHolidays = holidays.dates(sheetId);
        jdbc.query("SELECT id, claim_date, fixed_terms FROM claim WHERE sheet_id = ? AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ?",
                (rs, n) -> new long[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate().toEpochDay(),
                        rs.getInt("fixed_terms") },
                sheetId, Date.valueOf(from)).forEach((row) -> jdbc.update(
                        "UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?",
                        Date.valueOf(HolidayRepository.businessDaysAfter(sheetHolidays, LocalDate.ofEpochDay(row[1]),
                                (int) row[2])),
                        row[0], sheetId));
    }

    /** Records the user as the last to edit the claim. */
    public void markEdited(String sheetId, long id, String user) {
        jdbc.update("UPDATE claim SET edited_by = ? WHERE id = ? AND sheet_id = ?", user, id, sheetId);
    }

    /** The user who last edited the claim, or null when it was never edited. */
    public String editedBy(String sheetId, long id) {
        List<String> found = jdbc.queryForList("SELECT edited_by FROM claim WHERE sheet_id = ? AND id = ?",
                String.class, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person's claims, newest first. */
    public List<Claim> findForPerson(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC, id DESC",
                ClaimRepository::map, sheetId, personId);
    }

    /**
     * Move the claim to another person: it loses any figure a statement bound it to (live again) and is listed as
     * their newest claim; the claim as stored.
     */
    public Claim reassign(Claim claim, long personId) {
        jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL,"
                + " listed = NEXT VALUE FOR claim_listed_seq WHERE id = ? AND sheet_id = ?",
                personId, claim.id(), claim.sheetId());
        return find(claim.sheetId(), claim.id());
    }

    /** Bind the claim to a statement's figure (null: n/a), or unbind it (live again) when not stated. */
    public void bindStatement(Claim claim, boolean stated, BigDecimal statedDue) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ? AND sheet_id = ?",
                stated, stated ? statedDue : null, claim.id(), claim.sheetId());
    }

    /** Unbind (live again) each of the person's claims bound by their last statement. */
    public void unbindStatement(String sheetId, long personId) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ? AND stated",
                sheetId, personId);
    }

    /** Defer the claim until its {@code deferredUntil}. */
    public void defer(Claim claim) {
        jdbc.update("UPDATE claim SET deferred_until = ? WHERE id = ? AND sheet_id = ?",
                Date.valueOf(claim.deferredUntil()), claim.id(), claim.sheetId());
    }

    /** Store the claim's {@code number}. */
    public void renumber(Claim claim) {
        jdbc.update("UPDATE claim SET claim_number = ? WHERE id = ? AND sheet_id = ?",
                claim.number(), claim.id(), claim.sheetId());
    }

    /** Store the claim's {@code date} and {@code number}. */
    public void redate(Claim claim) {
        jdbc.update("UPDATE claim SET claim_date = ?, claim_number = ? WHERE id = ? AND sheet_id = ?",
                Date.valueOf(claim.date()), claim.number(), claim.id(), claim.sheetId());
    }

    /** Store the claim's {@code proofs} count. */
    public void saveProofs(Claim claim) {
        jdbc.update("UPDATE claim SET proofs = ? WHERE id = ? AND sheet_id = ?", claim.proofs(), claim.id(),
                claim.sheetId());
    }

    /** Mark the claim a late entry: added while the period containing its date was soft-closed. */
    public void markLateEntry(Claim claim) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE id = ? AND sheet_id = ?", claim.id(), claim.sheetId());
    }

    /** Whether the claim is a late entry. */
    public boolean lateEntry(String sheetId, long id) {
        return !jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND id = ? AND late_entry", Long.class,
                sheetId, id).isEmpty();
    }

    /** The ids of the sheet's late-entry claims. */
    public Set<Long> lateEntries(String sheetId) {
        return new HashSet<>(jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND late_entry", Long.class,
                sheetId));
    }

    /** Store the day the claim was last reminded. */
    public void remind(String sheetId, long id, LocalDate day) {
        jdbc.update("UPDATE claim SET reminded_on = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(day), id, sheetId);
    }

    /** The day the claim was last reminded, or null. */
    public LocalDate reminded(String sheetId, long id) {
        List<Date> found = jdbc.queryForList("SELECT reminded_on FROM claim WHERE sheet_id = ? AND id = ?", Date.class,
                sheetId, id);
        return found.isEmpty() || found.get(0) == null ? null : found.get(0).toLocalDate();
    }

    /** The day each of the sheet's reminded claims was last reminded, by claim id. */
    public Map<Long, LocalDate> remindedAll(String sheetId) {
        Map<Long, LocalDate> reminded = new HashMap<>();
        jdbc.query("SELECT id, reminded_on FROM claim WHERE sheet_id = ? AND reminded_on IS NOT NULL",
                (ResultSet rs) -> {
                    reminded.put(rs.getLong("id"), rs.getDate("reminded_on").toLocalDate());
                }, sheetId);
        return reminded;
    }

    /** Store the claim's external reference (null: none). */
    public void saveRef(Claim claim, String ref) {
        jdbc.update("UPDATE claim SET external_ref = ?, external_ref_key = ? WHERE id = ? AND sheet_id = ?", ref,
                ref == null ? null : ref.toLowerCase(Locale.ROOT), claim.id(), claim.sheetId());
    }

    /** Whether a claim on the sheet other than the one with id {@code except} (null: none) has the reference, ignoring case. */
    public boolean refUsed(String sheetId, String ref, Long except) {
        return !jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND external_ref_key = ? AND id <> ?",
                Long.class, sheetId, ref.toLowerCase(Locale.ROOT), except == null ? -1L : except).isEmpty();
    }

    /** The claim's external reference, or null. */
    public String ref(String sheetId, long id) {
        List<String> found = jdbc.queryForList("SELECT external_ref FROM claim WHERE sheet_id = ? AND id = ?",
                String.class, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The external reference of each of the sheet's claims that has one, by claim id. */
    public Map<Long, String> refs(String sheetId) {
        Map<Long, String> refs = new HashMap<>();
        jdbc.query("SELECT id, external_ref FROM claim WHERE sheet_id = ? AND external_ref IS NOT NULL",
                (ResultSet rs) -> {
                    refs.put(rs.getLong("id"), rs.getString("external_ref"));
                }, sheetId);
        return refs;
    }

    /** Store the reason the claim was voided with (null: none). */
    public void saveVoidReason(Claim claim, String reason) {
        jdbc.update("UPDATE claim SET void_reason = ? WHERE id = ? AND sheet_id = ?", reason, claim.id(),
                claim.sheetId());
    }

    /** The reason the claim was voided with, or null. */
    public String voidReason(String sheetId, long id) {
        List<String> found = jdbc.queryForList("SELECT void_reason FROM claim WHERE sheet_id = ? AND id = ?",
                String.class, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The reason each of the sheet's claims voided with one was voided with, by claim id. */
    public Map<Long, String> voidReasons(String sheetId) {
        Map<Long, String> reasons = new HashMap<>();
        jdbc.query("SELECT id, void_reason FROM claim WHERE sheet_id = ? AND void_reason IS NOT NULL",
                (ResultSet rs) -> {
                    reasons.put(rs.getLong("id"), rs.getString("void_reason"));
                }, sheetId);
        return reasons;
    }

    /** Store the claim's tags (stored form; null: none), adding each to the sheet's tag list. */
    public void saveTags(Claim claim, String tags) {
        jdbc.update("UPDATE claim SET tags = ? WHERE id = ? AND sheet_id = ?", tags, claim.id(), claim.sheetId());
        if (tags != null) {
            for (String tag : tags.split(",")) {
                jdbc.update("MERGE INTO claim_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", claim.sheetId(), tag);
            }
        }
    }

    /** The claim's tags (stored form), or null. */
    public String tags(String sheetId, long id) {
        List<String> found = jdbc.queryForList("SELECT tags FROM claim WHERE sheet_id = ? AND id = ?", String.class,
                sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The tags (stored form) of each of the sheet's claims that has any, by claim id. */
    public Map<Long, String> tagsAll(String sheetId) {
        Map<Long, String> tags = new HashMap<>();
        jdbc.query("SELECT id, tags FROM claim WHERE sheet_id = ? AND tags IS NOT NULL", (ResultSet rs) -> {
            tags.put(rs.getLong("id"), rs.getString("tags"));
        }, sheetId);
        return tags;
    }

    /** Every tag ever given to a claim on the sheet, sorted. */
    public List<String> usedTags(String sheetId) {
        return jdbc.queryForList("SELECT tag FROM claim_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
    }

    private static Claim map(ResultSet rs, int n) throws SQLException {
        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount").setScale(2), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
                ClaimStatus.valueOf(rs.getString("status")), rs.getString("claim_number"),
                rs.getBigDecimal("due"), rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
                rs.getString("corrects"), rs.getDate("due_by").toLocalDate(),
                rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate(),
                rs.getInt("proofs"), rs.getString("split_from"));
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PersonRepository {

    private static final String COLUMNS = "p.id, p.sheet_id, p.name, p.grade, p.version, p.statement_count, p.stated_total,"
            + " p.statement_date, p.retired_from, p.terms, p.contact FROM person p";

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in the order they were added. */
    public List<Person> findAll(String sheetId) {
        return withGrades(sheetId, jdbc.query("SELECT " + COLUMNS + " WHERE p.sheet_id = ? ORDER BY p.id",
                PersonRepository::map, sheetId));
    }

    /** The person with this id on this sheet, or null. */
    public Person find(String sheetId, long id) {
        List<Person> found = withGrades(sheetId, jdbc.query("SELECT " + COLUMNS + " WHERE p.sheet_id = ? AND p.id = ?",
                PersonRepository::map, sheetId, id));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on this sheet with this name or alias, ignoring case, or null. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = withGrades(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " WHERE p.sheet_id = ? AND (p.name_key = LOWER(?) OR EXISTS (SELECT 1 FROM"
                        + " person_alias a WHERE a.sheet_id = p.sheet_id AND a.person_id = p.id AND a.alias_key = LOWER(?)))",
                PersonRepository::map, sheetId, name, name));
        return found.isEmpty() ? null : found.get(0);
    }

    /**
     * Whether a person other than {@code exceptId} on the sheet has this name, or anyone on the sheet (themselves
     * included) has it as an alias, ignoring case.
     */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheetId, name, exceptId, exceptId);
        Integer a = jdbc.queryForObject("SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(?)",
                Integer.class, sheetId, name);
        return (n != null && n > 0) || (a != null && a > 0);
    }

    /** Whether a person other than {@code exceptId} on the sheet has this contact. */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND (? IS NULL OR id <> ?)",
                Integer.class, sheetId, contact, exceptId, exceptId);
        return n != null && n > 0;
    }

    /**
     * Insert a new person (null id) or update an existing one, bumping its version and storing its grades as
     * the person carries them; the person as stored, or null when the stored version is no longer the one the
     * person was loaded at. A new person's grade is recorded from the beginning of time.
     */
    public Person save(Person person) {
        if (person.id() != null) {
            int n = jdbc.update(
                    "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
                    person.name(), person.terms(), person.contact(), person.id(), person.sheetId(), person.version());
            if (n == 0) {
                return null;
            }
            jdbc.update("DELETE FROM person_grade WHERE person_id = ? AND sheet_id = ?", person.id(), person.sheetId());
            for (GradeFrom g : person.grades()) {
                insertGrade(person.sheetId(), person.id(), g);
            }
            return new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version() + 1,
                    person.statementCount(), person.statedTotal(), person.statementDate(), person.retiredFrom(),
                    person.holds(), person.grades(), person.terms(), person.contact());
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms, contact) VALUES (?, ?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, person.sheetId());
            ps.setString(2, person.name());
            ps.setString(3, person.grade());
            ps.setObject(4, person.terms());
            ps.setString(5, person.contact());
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        insertGrade(person.sheetId(), id, new GradeFrom(person.grade(), null));
        return new Person(id, person.sheetId(), person.name(), person.grade(), 0, 0, null, null, null, List.of())
                .withTerms(person.terms()).withContact(person.contact());
    }

    private void insertGrade(String sheetId, long personId, GradeFrom grade) {
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)", sheetId,
                personId, grade.grade(), grade.from() == null ? null : Date.valueOf(grade.from()));
    }

    /**
     * The people with the grades and holds recorded for them, each showing the grade in force on the sheet's today;
     * their holds oldest first.
     */
    private List<Person> withGrades(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ?", (rs) -> {
            grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                    .add(new GradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class)));
        }, sheetId);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id", (rs) -> {
            holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(new Hold(
                    rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
        }, sheetId);
        List<LocalDate> today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject("today", LocalDate.class), sheetId);
        LocalDate on = today.isEmpty() ? LocalDate.now() : today.get(0);
        List<Person> people = new ArrayList<>();
        for (Person p : found) {
            List<GradeFrom> own = grades.getOrDefault(p.id(), List.of(new GradeFrom(p.grade(), null)));
            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(own, on, p.grade()), p.version(),
                    p.statementCount(), p.statedTotal(), p.statementDate(), p.retiredFrom(),
                    List.copyOf(holds.getOrDefault(p.id(), List.of())), List.copyOf(own), p.terms(), p.contact()));
        }
        return people;
    }

    /**
     * Record a statement just taken of the person: one more statement, with its due-total and date; the
     * person as stored. Not an edit, so it leaves the version alone.
     */
    public Person recordStatement(Person person, String statedTotal, LocalDate date) {
        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ?"
                + " WHERE id = ? AND sheet_id = ?", statedTotal, Date.valueOf(date), person.id(), person.sheetId());
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date) VALUES (?, ?,"
                + " (SELECT statement_count FROM person WHERE id = ? AND sheet_id = ?), ?, ?)", person.sheetId(),
                person.id(), person.id(), person.sheetId(), statedTotal, Date.valueOf(date));
        return find(person.sheetId(), person.id());
    }

    /**
     * Cancel the person's last statement: one statement fewer, showing the due-total and date of the one before it
     * (none when it is not known); the person as stored. Not an edit, so it leaves the version alone.
     */
    public Person cancelStatement(Person person) {
        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq = ?", person.sheetId(),
                person.id(), person.statementCount());
        List<Map<String, Object>> before = jdbc.queryForList("SELECT stated_total, statement_date FROM person_statement"
                + " WHERE sheet_id = ? AND person_id = ? AND seq = ?", person.sheetId(), person.id(),
                person.statementCount() - 1);
        jdbc.update("UPDATE person SET statement_count = statement_count - 1, stated_total = ?, statement_date = ?"
                + " WHERE id = ? AND sheet_id = ?", before.isEmpty() ? null : before.get(0).get("stated_total"),
                before.isEmpty() ? null : before.get(0).get("statement_date"), person.id(), person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Retire the person from this date; the person as stored. Not an edit, so it leaves the version alone. */
    public Person retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(from), person.id(),
                person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Add a hold to the person; the person as stored. Not an edit, so it leaves the version alone. */
    public Person hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.sheetId(), person.id(), hold.from() == null ? null : Date.valueOf(hold.from()),
                hold.to() == null ? null : Date.valueOf(hold.to()));
        return find(person.sheetId(), person.id());
    }

    private static Person map(ResultSet rs, int n) throws SQLException {
